        # AC5/REG-2: without the env var the exported deadline is exactly
        # the pre-gh-1576 value.
        self.assertEqual(
            fa_agent_timeout.deadline_env_from(self.watch_env(), self.NOW_MS),
            {"FA_DEADLINE_EPOCH_MS": str(self.NOW_MS + 3_480_000)},
        )

