  if (bareInt != null) {
    if (bareInt < deadlineEpochMsFloor) {
      throw FormatException(
        '"$spec" is too small to be an epoch-ms timestamp — durations '
        'need a unit (e.g. ${bareInt}s, ${bareInt}m)',
