            fa_agent_timeout.deadline_env_from(
                clean_env_all(**{EXTERNAL_CAP_NAME: "1800"}), self.NOW_MS
            ),
            {"FA_DEADLINE_EPOCH_MS": str(self.NOW_MS + 1_680_000)},
        )

